// Card grid for docs/VARIANTS.mdx: a drawing (generated by tools/gen_swatches.py) above a name and one line of text.
// The drawing carries .pm-graphic, so the navbar graphics switch leaves the names and text.
import React from 'react';
import ThemedImage from '@theme/ThemedImage';
import useBaseUrl from '@docusaurus/useBaseUrl';

export function Card({img, title, children}) {
  const light = useBaseUrl(`/img/swatches/${img}.svg`);
  const dark = useBaseUrl(`/img/swatches/${img}-dark.svg`);
  return (
    <div className="pm-card">
      <div className="pm-graphic pm-card-img"><ThemedImage alt={title} sources={{light, dark}}/></div>
      <div className="pm-card-title">{title}</div>
      <div className="pm-card-text">{children}</div>
    </div>
  );
}

export default function Cards({children}) {
  return <div className="pm-cards">{children}</div>;
}
